claimNextDue(now = new Date()): FollowUp | null {
    const timestamp = now.toISOString();
    const expiry = new Date(now.getTime() - 60000).toISOString();
    const claim = this.database.transaction(() => {
      const row = this.database
        .prepare(
          `SELECT * FROM follow_ups
           WHERE ((status IN ('scheduled', 'retrying') AND due_at <= ?)
             OR (status = 'claimed' AND due_at <= ? AND claimed_at IS NOT NULL AND claimed_at <= ?))
           ORDER BY due_at ASC LIMIT 1`
        )
        .get(timestamp, timestamp, expiry) as Row | undefined;
      if (!row) return null;
      const result = this.database
        .prepare(
          `UPDATE follow_ups SET status = 'claimed', claimed_at = ?, attempt_count = attempt_count + 1
           WHERE id = ? AND ((status IN ('scheduled', 'retrying') AND due_at <= ?)
             OR (status = 'claimed' AND due_at <= ? AND claimed_at IS NOT NULL AND claimed_at <= ?))`
        )
        .run(timestamp, row.id, timestamp, timestamp, expiry);
      if (result.changes !== 1) return null;
      const claimed = this.database
        .prepare("SELECT * FROM follow_ups WHERE id = ?")
        .get(row.id) as Row;
      return followUpFromRow(claimed);
    });
    return claim();
  }
renewClaim(id, generation, now = new Date()) { const timestamp=now.toISOString(), cutoff=new Date(now.getTime()-60000).toISOString(); return this.database.transaction(() => this.database.prepare("UPDATE follow_ups SET claimed_at=? WHERE id=? AND status='claimed' AND attempt_count=? AND claimed_at>?").run(timestamp,id,generation,cutoff).changes===1)(); }
